#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO_ROOT=$(cd "$SCRIPT_DIR/.." && pwd)
SOURCE_JSONL="$REPO_ROOT/research/profitability/thebanks_eu/thebanks_eu_returns.jsonl"
OUTPUT_DIR="$REPO_ROOT/research/profitability/thebanks_eu/wayback_downloads"
URLS_FILE="$OUTPUT_DIR/profile_urls.txt"
CDX_DIR="$OUTPUT_DIR/cdx"
HTML_DIR="$OUTPUT_DIR/html"
CAPTURE_MANIFEST="$OUTPUT_DIR/captures.tsv"
FAILURES_FILE="$OUTPUT_DIR/failures.log"

banner "TheBanks.eu Wayback collector"

stage "Prepare the exact-bank manifest"
say "This creates a resumable download area and derives all 145 exact profile URLs."
for command_name in curl python3; do
  if ! command -v "$command_name" >/dev/null 2>&1; then
    warn "$command_name is required but was not found."
    exit 1
  fi
done
mkdir -p "$CDX_DIR" "$HTML_DIR"
: > "$FAILURES_FILE"
python3 - "$SOURCE_JSONL" "$URLS_FILE" <<'PY'
import json
import re
import sys
from pathlib import Path

source = Path(sys.argv[1])
destination = Path(sys.argv[2])
urls = set()
for line in source.read_text(encoding="utf-8").splitlines():
    if not line.strip():
        continue
    value = json.loads(line).get("source_url", "")
    match = re.fullmatch(r"https://thebanks\.eu/banks/(\d+)(?:/.*)?", value)
    if match:
        urls.add(f"https://thebanks.eu/banks/{match.group(1)}")

# Exact profiles for the four entities with no numeric record in the source JSONL.
urls.update({
    "https://thebanks.eu/banks/19654",  # Afin Bank Limited
    "https://thebanks.eu/banks/14486",  # Bank of Ireland (UK) Plc
    "https://thebanks.eu/banks/19245",  # SMBC Bank International plc
    "https://thebanks.eu/banks/14606",  # State Bank of India (UK) Limited
})
if len(urls) != 145:
    raise SystemExit(f"expected 145 exact profile URLs, found {len(urls)}")
destination.write_text("\n".join(sorted(urls, key=lambda u: int(u.rsplit('/', 1)[1]))) + "\n", encoding="utf-8")
PY
profile_count=$(wc -l < "$URLS_FILE" | tr -d ' ')
step "Prepared $profile_count exact profile URLs in $URLS_FILE."
note "Existing downloads are preserved and will be skipped on a rerun."
pause "Press Enter to test Wayback connectivity."

sample_url=$(head -n 1 "$URLS_FILE")
connectivity_tmp=$(mktemp)
if ! curl --fail --silent --show-error --location --retry 2 --retry-all-errors \
  --get "https://web.archive.org/cdx/search/cdx" \
  --data-urlencode "url=$sample_url" \
  --data-urlencode "output=json" \
  --data-urlencode "limit=1" \
  --output "$connectivity_tmp"; then
  rm -f "$connectivity_tmp"
  warn "Your terminal could not reach Wayback's CDX endpoint."
  open_url "https://web.archive.org/"
  step "If the homepage also fails, try another network or disable a blocking VPN/firewall."
  step "If the homepage works, rerun the wizard; Wayback may be rate-limiting the API temporarily."
  exit 1
fi
if ! python3 -m json.tool "$connectivity_tmp" >/dev/null 2>&1; then
  warn "Wayback responded, but not with valid JSON. The response is at $connectivity_tmp"
  exit 1
fi
rm -f "$connectivity_tmp"
step "Wayback CDX connectivity succeeded."
pause "Press Enter to enumerate captures."

stage "Enumerate Wayback captures"
say "The wizard queries 2021–2026 captures for each exact profile and its subpages."
index=0
while IFS= read -r profile_url; do
  index=$((index + 1))
  profile_id=${profile_url##*/}
  destination="$CDX_DIR/$profile_id.json"
  if [[ -s "$destination" ]] && python3 -m json.tool "$destination" >/dev/null 2>&1; then
    printf '\r  [%3d/%3d] profile %s (cached)       ' "$index" "$profile_count" "$profile_id"
    continue
  fi
  tmp="$destination.tmp"
  if curl --fail --silent --show-error --location --retry 4 --retry-all-errors \
    --get "https://web.archive.org/cdx/search/cdx" \
    --data-urlencode "url=$profile_url" \
    --data-urlencode "matchType=prefix" \
    --data-urlencode "output=json" \
    --data-urlencode "from=2021" \
    --data-urlencode "to=2026" \
    --data-urlencode "filter=statuscode:200" \
    --data-urlencode "filter=mimetype:text/html" \
    --data-urlencode "fl=timestamp,original,statuscode,mimetype,digest,length" \
    --data-urlencode "collapse=digest" \
    --output "$tmp" \
    && python3 -m json.tool "$tmp" >/dev/null 2>&1; then
    mv "$tmp" "$destination"
  else
    rm -f "$tmp"
    printf '%s\t%s\n' "$profile_id" "$profile_url" >> "$FAILURES_FILE"
  fi
  printf '\r  [%3d/%3d] profile %s                ' "$index" "$profile_count" "$profile_id"
  sleep 0.25
done < "$URLS_FILE"
printf '\n'
failure_count=$(wc -l < "$FAILURES_FILE" | tr -d ' ')
if [[ "$failure_count" -gt 0 ]]; then
  warn "$failure_count CDX queries failed; rerunning the wizard will retry only those profiles."
fi
step "Capture indexes are saved under $CDX_DIR."
pause "Press Enter to build the download manifest."

stage "Download archived HTML"
say "Only canonical profile and standard subpage routes are selected; duplicate content is removed."
python3 - "$CDX_DIR" "$CAPTURE_MANIFEST" <<'PY'
import csv
import json
import re
import sys
from pathlib import Path
from urllib.parse import urlparse

cdx_dir = Path(sys.argv[1])
manifest = Path(sys.argv[2])
allowed = re.compile(r"^/banks/(\d+)(?:/(financials|market_share|credit_ratings|bank_identifiers|similar_banks))?/?$")
rows = {}
for source in sorted(cdx_dir.glob("*.json")):
    try:
        data = json.loads(source.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        continue
    if not data or len(data) < 2:
        continue
    header = data[0]
    for raw in data[1:]:
        record = dict(zip(header, raw))
        timestamp = record.get("timestamp", "")
        original = record.get("original", "")
        digest = record.get("digest", "")
        match = allowed.fullmatch(urlparse(original).path)
        if not match or not re.fullmatch(r"\d{14}", timestamp):
            continue
        profile_id = match.group(1)
        route = match.group(2) or "profile"
        key = (profile_id, route, digest or timestamp)
        # One replay per unique body; retain the earliest timestamp exposing it.
        if key in rows and rows[key][0] <= timestamp:
            continue
        filename = f"{timestamp}_{route}.html"
        relative = f"html/{profile_id}/{filename}"
        rows[key] = (timestamp, original, digest, relative)

ordered = sorted(
    ((key[0], *value) for key, value in rows.items()),
    key=lambda row: (int(row[0]), row[1], row[2]),
)
with manifest.open("w", encoding="utf-8", newline="") as handle:
    writer = csv.writer(handle, delimiter="\t", lineterminator="\n")
    writer.writerow(["profile_id", "timestamp", "original", "digest", "local_path"])
    writer.writerows(ordered)
PY
capture_count=$(awk 'NR > 1 {count++} END {print count+0}' "$CAPTURE_MANIFEST")
step "Found $capture_count unique archived page bodies to download."
if [[ "$capture_count" -eq 0 ]]; then
  warn "No qualifying captures were returned. Keep the CDX files and reply with the failure details."
  exit 1
fi
if ! confirm "Download the $capture_count archived HTML pages now?"; then
  note "Nothing was deleted. Rerun the wizard later to continue."
  exit 0
fi

download_index=0
tail -n +2 "$CAPTURE_MANIFEST" | while IFS=$'\t' read -r profile_id timestamp original digest local_path; do
  download_index=$((download_index + 1))
  destination="$OUTPUT_DIR/$local_path"
  mkdir -p "$(dirname "$destination")"
  if [[ -s "$destination" ]]; then
    printf '\r  [%4d/%4d] %s (cached)       ' "$download_index" "$capture_count" "$profile_id"
    continue
  fi
  replay_url="https://web.archive.org/web/${timestamp}id_/${original}"
  tmp="$destination.tmp"
  if curl --fail --silent --show-error --location --retry 4 --retry-all-errors \
    --user-agent "Mozilla/5.0 (compatible; KatalysisResearch/1.0)" \
    --output "$tmp" "$replay_url"; then
    mv "$tmp" "$destination"
  else
    rm -f "$tmp"
    printf '%s\t%s\t%s\n' "$profile_id" "$timestamp" "$replay_url" >> "$FAILURES_FILE"
  fi
  printf '\r  [%4d/%4d] %s                ' "$download_index" "$capture_count" "$profile_id"
  sleep 0.25
done
printf '\n'
step "Archived pages are saved under $HTML_DIR."
pause "Press Enter for the verification summary."

stage "Verify and hand off"
cdx_count=$(find "$CDX_DIR" -type f -name '*.json' -size +0c | wc -l | tr -d ' ')
html_count=$(find "$HTML_DIR" -type f -name '*.html' -size +0c | wc -l | tr -d ' ')
failure_count=$(wc -l < "$FAILURES_FILE" | tr -d ' ')
say "Collection summary:"
step "$profile_count exact profile URLs"
step "$cdx_count valid CDX response files"
step "$capture_count unique capture candidates"
step "$html_count downloaded HTML files"
if [[ "$failure_count" -gt 0 ]]; then
  warn "$failure_count requests need retry; details are in $FAILURES_FILE."
else
  step "No request failures recorded."
fi
python3 - "$OUTPUT_DIR/RUN_COMPLETE.txt" "$profile_count" "$cdx_count" "$capture_count" "$html_count" "$failure_count" <<'PY'
import sys
from datetime import datetime, timezone
from pathlib import Path

path = Path(sys.argv[1])
labels = ("profiles", "cdx_files", "capture_candidates", "html_files", "failures")
values = sys.argv[2:]
lines = [f"completed_utc={datetime.now(timezone.utc).isoformat()}"]
lines.extend(f"{key}={value}" for key, value in zip(labels, values))
path.write_text("\n".join(lines) + "\n", encoding="utf-8")
PY
say "Reply 'done' in the Codex conversation. I can then inspect the local archived pages."
note "Output: $OUTPUT_DIR"
pause "Press Enter to finish."

finish
